17	  /** Search the full model label list (not just detected species) so manual boxes can name any species. */
18	  async function searchAllLabels(query: string): Promise<EnrichedSpeciesSummary[]> {
19	    const scientific = (await searchByCommonName(query)).slice(0, 20);
20	    if (scientific.length === 0) return [];
21	    const common = await resolveAllLabels(scientific);
22	    return scientific.map((scientific_name) => ({
23	      scientific_name,
24	      common_name: common[scientific_name] ?? scientific_name,
25	      location_count: 0,
26	      detection_count: 0,
27	      last_detected: '',
28	      avg_confidence: 0,
29	    }));
30	  }
31	
32	  const selected = $derived(getSelectedBox());
33	
34	  // eslint-disable-next-line @typescript-eslint/no-empty-function
35	  function noop(): void {}
