1	<script lang="ts">
2	  import { X, Trash, Copy, ChevronDown, ChevronUp } from '@lucide/svelte';
3	  import { appState } from '$lib/stores/app.svelte';
4	  import { logState, clearLog, type LogEntry } from '$lib/stores/log.svelte';
5	  import * as m from '$paraglide/messages';
6	
7	  let scrollContainer: HTMLDivElement | undefined = $state();
8	  let autoScroll = $state(true);
9	  let collapsed = $state(false);
10	
11	  function formatTime(ts: number): string {
12	    const d = new Date(ts);
13	    return d.toLocaleTimeString('en-GB', { hour12: false }) + '.' + String(d.getMilliseconds()).padStart(3, '0');
14	  }
15	
16	  function levelColor(level: LogEntry['level']): string {
17	    switch (level) {
18	      case 'error':
19	        return 'text-error';
20	      case 'warn':
21	        return 'text-warning';
22	      case 'debug':
23	        return 'text-neutral-content/40';
24	      default:
25	        return 'text-neutral-content/60';
26	    }
27	  }
28	
29	  function levelBadgeColor(level: LogEntry['level']): string {
30	    switch (level) {
31	      case 'error':
32	        return 'bg-error/15 text-error';
33	      case 'warn':
34	        return 'bg-warning/15 text-warning';
35	      case 'debug':
36	        return 'bg-neutral-content/10 text-neutral-content/40';
37	      default:
38	        return 'bg-info/15 text-info';
39	    }
40	  }
41	
42	  function handleScroll() {
43	    if (!scrollContainer) return;
44	    const { scrollTop, scrollHeight, clientHeight } = scrollContainer;
45	    autoScroll = scrollHeight - scrollTop - clientHeight < 30;
46	  }
47	
48	  function scrollToBottom() {
49	    if (scrollContainer && autoScroll) {
50	      scrollContainer.scrollTop = scrollContainer.scrollHeight;
51	    }
52	  }
53	
54	  async function copyLog() {
55	    const text = logState.entries
56	      .map((e) => `[${formatTime(e.timestamp)}] [${e.level.toUpperCase()}] [${e.source}] ${e.message}`)
57	      .join('\n');
58	    await navigator.clipboard.writeText(text);
59	  }
60	
61	  // Auto-scroll when entries change
62	  $effect(() => {
63	    // Read length to register a reactive dependency so the effect re-runs on new entries.
64	    // eslint-disable-next-line @typescript-eslint/no-meaningless-void-operator -- intentional reactive-dependency read
65	    void logState.entries.length;
66	    requestAnimationFrame(scrollToBottom);
67	  });
68	</script>
69	
70	{#if appState.showLogPanel}
71	  <div class="border-base-300 bg-base-200 flex flex-col border-t" style="height: {collapsed ? 'auto' : '220px'}">
72	    <!-- Header -->
73	    <div class="border-base-300 bg-base-300/50 flex items-center gap-2 border-b px-3 py-1.5">
74	      <button
75	        class="btn btn-ghost btn-xs btn-square"
76	        onclick={() => (collapsed = !collapsed)}
77	        title={collapsed ? m.log_expand() : m.log_collapse()}
78	      >
79	        {#if collapsed}
80	          <ChevronUp size={14} />
81	        {:else}
82	          <ChevronDown size={14} />
83	        {/if}
84	      </button>
85	      <span class="text-base-content/60 text-xs font-semibold uppercase">{m.log_title()}</span>
86	      <span class="badge badge-sm badge-ghost tabular-nums">{logState.entries.length}</span>
87	
88	      <div class="flex-1"></div>
89	
90	      <button class="btn btn-ghost btn-xs btn-square" onclick={copyLog} title={m.log_copyToClipboard()}>
91	        <Copy size={13} />
92	      </button>
93	      <button class="btn btn-ghost btn-xs btn-square" onclick={clearLog} title={m.log_clear()}>
94	        <Trash size={13} />
95	      </button>
96	      <button
97	        class="btn btn-ghost btn-xs btn-square"
98	        onclick={() => (appState.showLogPanel = false)}
99	        title={m.log_close()}
100	      >
101	        <X size={13} />
102	      </button>
103	    </div>
104	
105	    <!-- Log entries -->
106	    {#if !collapsed}
107	      <div
108	        bind:this={scrollContainer}
109	        onscroll={handleScroll}
110	        class="bg-neutral flex-1 overflow-auto p-1 font-mono text-[11px] leading-[18px]"
111	      >
112	        {#if logState.entries.length === 0}
113	          <div class="text-neutral-content/50 p-3 text-center">{m.log_empty()}</div>
114	        {:else}
115	          {#each logState.entries as entry (entry.id)}
116	            <div class="hover:bg-neutral-content/5 flex gap-1 px-1">
117	              <span class="text-neutral-content/50 shrink-0">{formatTime(entry.timestamp)}</span>
118	              <span class="shrink-0 rounded px-1 {levelBadgeColor(entry.level)}"
119	                >{entry.level.toUpperCase().padEnd(5)}</span
120	              >
121	              <span class="text-info shrink-0">[{entry.source}]</span>
122	              <span class="{levelColor(entry.level)} break-all whitespace-pre-wrap">{entry.message}</span>
123	            </div>
124	          {/each}
125	        {/if}
126	      </div>
127	    {/if}
128	  </div>
129	{/if}
